package com.sih.gap.service; import com.sih.gap.dto.SmartQueueDtos.*; import com.sih.gap.entity.*; import com.sih.gap.entity.QueueTicket.*; import com.sih.gap.repository.*; import com.sih.shared.tenant.TenantContext; import java.time.*; import java.util.*; import java.util.concurrent.*; import org.springframework.http.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import org.springframework.web.server.*; @Service @Transactional public class SmartQueueService{final QueueTicketRepository tickets;final PatientRepository patients;public SmartQueueService(QueueTicketRepository t,PatientRepository p){tickets=t;patients=p;}String tenant(){return TenantContext.requireCurrentTenant();}public Ticket checkIn(CheckInRequest r){var p=patients.findById(r.patientId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));var q=QueueTicket.builder().patient(p).ticketNumber("Q-"+LocalDate.now().toString().replace("-","")+"-"+String.format("%03d",ThreadLocalRandom.current().nextInt(1,1000))).serviceArea(r.serviceArea()).acuity(r.acuity()).chiefComplaint(r.chiefComplaint()).painScore(r.painScore()).oxygenSaturation(r.oxygenSaturation()).heartRate(r.heartRate()).build();return map(tickets.save(q));}public QueueView queue(String area){var w=tickets.findByTenantIdAndServiceAreaAndStatusOrderByCheckedInAtAsc(tenant(),area,Status.WAITING);return new QueueView(w.stream().map(this::map).toList(),w.stream().min(Comparator.comparingInt(this::score).thenComparing(QueueTicket::getCheckedInAt)).map(this::map).orElse(null),tickets.findTop5ByTenantIdAndServiceAreaAndStatusOrderByCalledAtDesc(tenant(),area,Status.CALLED).stream().map(x->new PublicTicket(x.getTicketNumber(),x.getServiceArea(),x.getStatus(),x.getCalledAt())).toList());}public Ticket callNext(String area,String clinician){var n=queue(area).nextCandidate();if(n==null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Aucun patient en attente");var q=tickets.findByIdAndTenantId(n.id(),tenant()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));q.setStatus(Status.CALLED);q.setCalledAt(OffsetDateTime.now());q.setAssignedClinicianId(clinician);return map(q);}public List<PublicTicket> display(String area){return tickets.findTop5ByTenantIdAndServiceAreaAndStatusOrderByCalledAtDesc(tenant(),area,Status.CALLED).stream().map(x->new PublicTicket(x.getTicketNumber(),x.getServiceArea(),x.getStatus(),x.getCalledAt())).toList();}int score(QueueTicket q){int base=switch(q.getAcuity()){case P1_IMMEDIATE->0;case P2_VERY_URGENT->100;case P3_URGENT->200;case P4_STANDARD->300;case P5_ROUTINE->400;};long mins=Duration.between(q.getCheckedInAt(),OffsetDateTime.now()).toMinutes();return base-(int)Math.min(90,mins/5);}Ticket map(QueueTicket q){return new Ticket(q.getId(),q.getTicketNumber(),q.getServiceArea(),q.getAcuity(),q.getStatus(),q.getPatient().getFullName(),q.getCheckedInAt(),q.getCalledAt());}}